css:
.wrap { max-width: 1360px; margin: 0 auto; }
section { padding: 90px 40px; position: relative; z-index: 2; }

.section-eyebrow {
  display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 64px;
}
.section-eyebrow .label { font-family: 'JetBrains Mono', monospace; font-size: 12px; color: var(--accent); letter-spacing: 0.2em; text-transform: uppercase; }
.section-eyebrow .label span { color: var(--text-faint); }
.section-eyebrow .index { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-faint); }

@media (max-width: 700px) {
  section { padding: 64px 20px; }
  .section-eyebrow { margin-bottom: 40px; }
}

.demo-heading { font-weight: 600; font-size: clamp(32px, 4vw, 56px); letter-spacing: -0.03em; line-height: 1; }
.demo-heading span { color: var(--accent); }
